arget(TEventHandler *target);		// return true if the relationship between this view and the target		// determines that the border should be drawn	//------------------------------------------------------------------------------------	// data members	//------------------------------------------------------------------------------------public:	IDType	fTargetView;};EXPORT_MA  void InitUTargetBorderView();#endif/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		04/17/96	InitUTargetBorderView		04/15/96	Phase 1 of View Breakup changes		----- Release 10 -----*/